/* From Uiverse.io by ainasoa - Tags: input */
.__UIV_SCOPE__ .input {
  max-width: 210px;
  height: 50px;
  border-radius: 7px;
  border: 0;
  outline: auto grey;
  padding-inline: 15px;
  font-size: 16px;
  transform: all 200ms;
}

.__UIV_SCOPE__ .input:focus {
  text-decoration: underline 6px;
  box-shadow: 0 0 50px rgb(255, 255, 255);
  border: 1px solid grey;
}
